const item = $input.first()?.json || {};
const data = item.body || item;

const ticketId = Number(data.ticket_id || data.id || 1);
const content = data.content_original || data.message || data.text || data.issue_description || '';
const category = (data.category || data.intent || '').toUpperCase();
const priority = (data.priority || data.urgency || 'P2').toUpperCase();

return [{
  json: {
    ticket_id: ticketId,
    content_original: content,
    category: category,
    priority: priority
  }
}];

const data = $input.first().json;
const contentLower = (data.content_original || '').toLowerCase();
const cat = data.category;

let deptId = 1;
let deptCode = 'SUPPORT';
let deptName = 'Chăm sóc khách hàng';

if (cat === 'WARRANTY' || cat === 'PRODUCT' || contentLower.includes('bảo hành') || contentLower.includes('liệt phím') || contentLower.includes('sọc màn hình') || contentLower.includes('hỏng') || contentLower.includes('lỗi kỹ thuật') || contentLower.includes('tai nghe') || contentLower.includes('bàn phím') || contentLower.includes('laptop')) {
  deptId = 4;
  deptCode = 'TECH';
  deptName = 'Kỹ thuật & Bảo hành';
} else if (cat === 'DELIVERY' || contentLower.includes('giao hàng') || contentLower.includes('shipper') || contentLower.includes('giao trễ') || contentLower.includes('chậm giao') || contentLower.includes('vỡ hộp') || contentLower.includes('móp méo')) {
  deptId = 3;
  deptCode = 'DELIVERY';
  deptName = 'Giao hàng & Vận chuyển';
} else if (cat === 'REFUND' || cat === 'PAYMENT' || contentLower.includes('hoàn tiền') || contentLower.includes('trừ tiền') || contentLower.includes('thanh toán') || contentLower.includes('chuyển khoản') || contentLower.includes('hóa đơn')) {
  deptId = 5;
  deptCode = 'ACCOUNTING';
  deptName = 'Kế toán & Thanh toán';
} else if (cat === 'STAFF' || contentLower.includes('thái độ') || contentLower.includes('cộc lốc') || contentLower.includes('nhân viên phục vụ') || contentLower.includes('tư vấn sai')) {
  deptId = 6;
  deptCode = 'SALES';
  deptName = 'Kinh doanh & Quản lý';
} else if (cat === 'LEGAL' || contentLower.includes('kiện') || contentLower.includes('công an') || contentLower.includes('báo chí') || contentLower.includes('lừa đảo') || contentLower.includes('tố cáo')) {
  deptId = 7;
  deptCode = 'LEGAL';
  deptName = 'Pháp chế & Khiếu nại';
} else if (cat === 'WAREHOUSE' || contentLower.includes('đóng gói') || contentLower.includes('thiếu phụ kiện') || contentLower.includes('thiếu quà')) {
  deptId = 2;
  deptCode = 'WAREHOUSE';
  deptName = 'Kho & Đóng gói';
}

return [{
  json: {
    ...data,
    department_id: deptId,
    department_code: deptCode,
    department_name: deptName
  }
}];

const deptInfo = $('Code - Xác định phòng ban chuyên trách').first().json;
const foundStaff = $input.first()?.json || {};

const staffId = foundStaff.staff_id || 4;
const staffName = foundStaff.staff_name || 'Nhân viên CSKH';
const staffEmail = foundStaff.staff_email || 'agent@support.local';
const currentLoad = Number(foundStaff.current_load || 0);
const newLoad = currentLoad + 1;

return [{
  json: {
    ticket_id: deptInfo.ticket_id,
    department_id: deptInfo.department_id,
    department_name: deptInfo.department_name,
    department_code: deptInfo.department_code,
    staff_id: staffId,
    staff_name: staffName,
    staff_email: staffEmail,
    current_load: currentLoad,
    new_load: newLoad,
    telegram_chat_id: foundStaff.telegram_chat_id || '7919420845'
  }
}];

const res = $('Code - Chuẩn bị thông tin gán việc').first().json;

return [{
  json: {
    success: true,
    ticket_id: res.ticket_id,
    department_id: res.department_id,
    department_name: res.department_name,
    department_code: res.department_code,
    assigned_staff_id: res.staff_id,
    assigned_staff_name: res.staff_name,
    assigned_staff_email: res.staff_email,
    assigned_at: new Date().toISOString()
  }
}];
